int parseIntDef(const std::string& raw, int def) {
    // trim (chars <= ' ', matching AnsiString::Trim)
    size_t b = 0, e = raw.size();
    while (b < e && static_cast<unsigned char>(raw[b]) <= ' ') ++b;
    while (e > b && static_cast<unsigned char>(raw[e - 1]) <= ' ') --e;
    if (b >= e) return def;
    std::string s = raw.substr(b, e - b);

    const char* p = s.c_str();
    char* end = 0;
    long v;
    if (s.size() >= 1 && s[0] == '$') {                 // Pascal hex literal
        v = std::strtol(p + 1, &end, 16);
        if (end == p + 1 || *end != '\0') return def;
    } else if (s.size() >= 2 && s[0] == '0' &&
               (s[1] == 'x' || s[1] == 'X')) {          // C hex literal
        v = std::strtol(p, &end, 16);
        if (end == p || *end != '\0') return def;
    } else {                                            // decimal
        v = std::strtol(p, &end, 10);
        if (end == p || *end != '\0') return def;
    }
    return static_cast<int>(v);
}

TIniFile::TIniFile(const AnsiString& fileName)
    : FileName(fileName), writeThrough_(true) {
    // Win32 TIniFile binds lazily, and so does this one: NOTHING is loaded here.   // AI(W906-A5-INIREAD) 20260924: was an eager store_.LoadFromFile(fileName) -- the image every read used to answer from
    // Every Read*/ValueExists/SectionExists/ReadSection(s) re-reads the file (IniFiles.cpp EOF); a missing file => defaults.
    // (store_ is read only by the TMemIniFile variant; WriteString still mirrors into it, which is harmless.)   //AI(W906-BOOTSPEED-2) 20260929: no longer true -- harmless for results but O(keys) per write; the write-through TIniFile now leaves store_ empty (WriteString)
}

AnsiString TIniFile::ReadString(const AnsiString& section, const AnsiString& ident,
                                const AnsiString& def) {
    bool found = false;
    AnsiString v = writeThrough_ ? W906_DiskIniReadRaw(FileName, section, ident, found) : store_.ReadRaw(section, ident, found);   // AI(W906-A5-INIREAD) 20260924: write-through reads the CURRENT file like GetPrivateProfileStringA (BCB6 2048-byte buffer)
    return found ? v : (writeThrough_ ? W906_Win32ProfileDefault(def) : def);   // AI(W906-A5-INIREAD) 20260924: Win32 hands back the default minus its trailing SPACES, cut to 2047 bytes
}

int TIniFile::ReadInteger(const AnsiString& section, const AnsiString& ident, int def) {
    bool found = false;
    AnsiString v = writeThrough_ ? W906_DiskIniReadRaw(FileName, section, ident, found) : store_.ReadRaw(section, ident, found);   // AI(W906-A5-INIREAD) 20260924: write-through reads the CURRENT file like GetPrivateProfileStringA (BCB6 2048-byte buffer)
    if (!found) return def;
    return parseIntDef(v.str(), def);
}

void TIniFile::WriteString(const AnsiString& section, const AnsiString& ident,
                           const AnsiString& value) {
    if (!writeThrough_) store_.WriteRaw(section, ident, value);   //AI(W906-BOOTSPEED-2) 20260929: the in-memory mirror is only READ by the TMemIniFile variant (every write-through read/ValueExists/ReadSection goes to disk, flush() runs only when !writeThrough_) -- mirroring here grew a never-read copy of every key and made each write O(keys) (boot sample: TIniStore::iequal < WriteRaw ~10 of 46 s in W906_SecurityJamBoot, whose one INIFile collects ~23,000 keys of JAM0000.dat)
    if (writeThrough_) { void W906_Win32WriteProfileString(const AnsiString&, const AnsiString&, const AnsiString&, const AnsiString&); W906_Win32WriteProfileString(FileName, section, ident, value); }   // AI(W906-T4-INIFMT2) 20260924: in-place edit of the CURRENT disk file like Win32 WritePrivateProfileStringA (was flush() = rebuild the whole file from the image loaded at construction) -- see EOF
}

void TIniFile::UpdateFile() {
    // TIniFile: Win32 writes are immediate -> commit / no-op.  For the Mem
    // variant (writeThrough_==false) this is the ONLY disk flush.
    if (!writeThrough_)
        flush();
}

// ===========================================================================
//  vclcompat/IniFiles.h
//  BCB6 (Borland C++ Builder 6) TIniFile / TMemIniFile compatibility shim.
//
//  PURPOSE
//  -------
//  Recreate ONLY the TIniFile / TMemIniFile API surface that the HT9011UC
//  V906 BCB6 source actually drives -- specifically the common.cpp ini-helper
//  family (OpenIniFile / CheckAndReadIniData* / ReadIniData* / WriteIniData* /
//  CheckSectionExist / CheckKeyExist / *General / *Mem variants) -- with
//  semantics that mirror BCB6 EXACTLY, so the config-reader gateway translates
//  faithfully and low-risk.
//
//  WHY TWO CLASSES
//  ---------------
//  BCB6:
//    * TIniFile    -- a thin wrapper over the Win32 profile API
//                     (GetPrivateProfileString / WritePrivateProfileString).
//                     Win32 writes are IMMEDIATE; UpdateFile() is effectively a
//                     commit / no-op (but the method MUST exist -- callers call
//                     it before delete).  Win32 has a ~32KB-per-section read cap.
//    * TMemIniFile -- loads the ENTIRE file into memory (the whole point: avoid
//                     the 32KB/section cap).  Reads/writes hit the in-memory
//                     image; UpdateFile() is the ONLY thing that flushes the
//                     in-memory image back to disk.
//
//  In this portable layer TMemIniFile is backed by an in-memory store (TIniStore)
//  and TIniFile READS the file itself on every call (AI(W906-A5-INIREAD) 20260924:
//  Win32 GetPrivateProfileStringA rules measured vs kernel32, IniFiles.cpp EOF).  FLUSH POLICY:
//    * TIniFile    -- every mutating call writes through to disk immediately
//                     (mirrors Win32 immediate-write).  UpdateFile() is a no-op
//                     commit.  (The 32KB cap is a Win32 artefact and is NOT
//                     reproduced -- it was never desirable behaviour and no
//                     correct caller relies on truncation.)
//    * TMemIniFile -- mutations touch memory only; disk is written by
//                     UpdateFile() (and by the destructor as a safety net,
//                     matching the BCB6 idiom that always pairs UpdateFile()
//                     with delete -- see common.cpp CloseIniFileMem 362-363).
//
//  BCB6 SEMANTICS REPLICATED (verified against the golden ref ini-helper family
//  D:\HT9045\HT9011UC_Code_V3.33.906.0_20260618\common.cpp:148-1487):
//    * DEFAULT FALLBACK: every Read*(Section,Ident,Default) returns Default
//      VERBATIM when the section OR key is absent (or the stored value is
//      unparseable for the numeric flavours).                       (common.cpp passim)
//    * CASE-INSENSITIVE section + key matching (Win32 profile + Delphi TStrings
//      name lookup are both case-insensitive).
//    * ReadInteger: BCB6 StrToIntDef-like parse -- decimal, or Pascal '$'/'0x'
//      hex prefix; leading sign tolerated; unparseable -> Default.   (common.cpp:428,445,548,604,987,1452)
//    * ReadFloat : locale-independent decimal parse ('.' separator);
//      unparseable -> Default.                                        (common.cpp:411,534,590,890,1440)
//    * ReadBool  : stored as '0'/'1'; nonzero integer => true; unparseable or
//      missing -> Default.                                            (common.cpp:462,520,576,636,1462)
//    * Doubles are persisted as '%0.4f' TEXT via WriteString (NOT WriteFloat)
//      and re-read via ReadFloat -- replicate the 4-decimal string round-trip.
//      There is NO WriteFloat call anywhere in common.cpp's ini family.
//                                                                     (common.cpp:407/409,888/958,1435/1438,1479)
//    * ReadDateTime / WriteDateTime : stored/parsed as a date+time STRING using
//      the app/system short-date+time format (here: DateTimeToStr /
//      StrToDateTime); missing -> Default.                            (common.cpp:504,506,1113)
//    * WriteString/WriteInteger/WriteBool/WriteDateTime create the section and
//      key if absent.
//    * ValueExists(Section,Ident) -> true iff the key exists under [Section] (TIniFile: in BCB6's ReadSection list, A5).
//      SectionExists(Section)     -> TMemIniFile: the [Section] header exists; TIniFile (A5): the section has >= 1 key (BCB6).
//    * FileName is a read-only property returning the bound path; OpenIniFile /
//      OpenIniFileMem compare INIFile->FileName!=FileName to decide reuse.
//                                                                     (common.cpp:328,350)
//
//  BIG5 / ENCODING: keys and values that this family reads/writes are ASCII;
//  section names and value strings MAY contain Big5 bytes.  The store keeps
//  raw bytes (std::string) untouched, so Big5 round-trips byte-for-byte.  Key
//  and section MATCHING is ASCII case-insensitive (toupper on bytes < 0x80);
//  Big5 lead/trail bytes (>=0x80) are compared verbatim, never case-folded,
//  which is safe because the matched identifiers in this family are ASCII.
//
//  Out of scope (not used by this batch): ReadBinaryStream / WriteBinaryStream,
//  EraseSection, DeleteKey, ReadSectionValues into a TStrings of "k=v" pairs
//  beyond the simple ReadSection / ReadSections enumerators provided here.
// ===========================================================================
#ifndef VCLCOMPAT_INIFILES_H
#define VCLCOMPAT_INIFILES_H

#include "vclcompat/AnsiString.h"
#include "vclcompat/TDateTime.h"
#include "vclcompat/TStringList.h"   // ReadSection(s) fill a TStrings*

#include <string>
#include <vector>

namespace vclcompat {

// ---------------------------------------------------------------------------
//  TIniStore -- shared in-memory representation of an INI file.
//
//  Preserves SECTION and KEY insertion order (BCB6 TStrings-backed ini keeps
//  order), keeps RAW value bytes (Big5-safe), and matches section/key names
//  ASCII-case-insensitively.  This is an implementation detail shared by
//  TIniFile and TMemIniFile; translated source never names it.
// ---------------------------------------------------------------------------
class TIniStore {
public:
    // ---- queries ----------------------------------------------------------
    bool       SectionExists(const AnsiString& section) const;
    bool       ValueExists(const AnsiString& section, const AnsiString& ident) const;
    // Returns the raw stored string for [section]ident, or `found=false` if
    // section/key absent (caller substitutes Default).
    AnsiString ReadRaw(const AnsiString& section, const AnsiString& ident,
                       bool& found) const;
    // ---- mutation ---------------------------------------------------------
    void       WriteRaw(const AnsiString& section, const AnsiString& ident,
                        const AnsiString& value);
    // ---- enumeration (BCB6 ReadSection / ReadSections) --------------------
    void       FillSectionKeys(const AnsiString& section, TStrings* dest) const;
    void       FillSectionNames(TStrings* dest) const;

    // ---- disk I/O ---------------------------------------------------------
    void       LoadFromFile(const AnsiString& path);   // replaces store; missing file => empty
    void       SaveToFile(const AnsiString& path, bool blankLineAfterSection = false) const;  // AI(W906-T4-INIFMT) 20260924: true = BCB6 TMemIniFile layout (see IniFiles.cpp flush)

private:
    struct KeyVal { std::string key; std::string val; };
    struct Section { std::string name; std::vector<KeyVal> items; };

    std::vector<Section> sections_;

    // ASCII case-insensitive byte compare (Big5 high bytes compared verbatim).
    static bool iequal(const std::string& a, const std::string& b);
    Section*       findSection(const AnsiString& name);
    const Section* findSection(const AnsiString& name) const;
};

// ===========================================================================
//  TIniFile  -- Win32-profile semantics: writes flush to disk immediately.
//               UpdateFile() is a commit/no-op (must exist; callers call it
//               before delete -- common.cpp:340,362,1418).
// ===========================================================================
class TIniFile {
public:
    explicit TIniFile(const AnsiString& fileName);
    virtual ~TIniFile();

    // ---- bound path (BCB6 read-only property TIniFile::FileName) ----------
    // Exposed as a public field so the source idiom `INIFile->FileName` (a
    // property read, common.cpp:328,350) compiles unchanged.  It is set once in
    // the ctor and never reassigned (read-only in spirit).
    AnsiString FileName;

    // ---- existence checks -------------------------------------------------
    bool SectionExists(const AnsiString& section);
    bool ValueExists(const AnsiString& section, const AnsiString& ident);

    // ---- typed reads (Default returned on miss/parse-failure) -------------
    AnsiString ReadString (const AnsiString& section, const AnsiString& ident, const AnsiString& def);
    int        ReadInteger(const AnsiString& section, const AnsiString& ident, int def);
    double     ReadFloat  (const AnsiString& section, const AnsiString& ident, double def);
    bool       ReadBool   (const AnsiString& section, const AnsiString& ident, bool def);
    TDateTime  ReadDateTime(const AnsiString& section, const AnsiString& ident, const TDateTime& def);

    // ---- typed writes (create section/key if absent) ---------------------
    void WriteString  (const AnsiString& section, const AnsiString& ident, const AnsiString& value);
    void WriteInteger (const AnsiString& section, const AnsiString& ident, int value);
    void WriteBool    (const AnsiString& section, const AnsiString& ident, bool value);
    void WriteDateTime(const AnsiString& section, const AnsiString& ident, const TDateTime& value);

    // ---- enumeration ------------------------------------------------------
    void ReadSection (const AnsiString& section, TStrings* dest); // key names under [section]
    void ReadSections(TStrings* dest);                            // all section names

    // ---- flush ------------------------------------------------------------
    // TIniFile: no-op commit (Win32 writes are immediate; the store already
    // wrote through to disk on each mutation).  MUST exist (common.cpp:340).
    void UpdateFile();

protected:
    TIniStore store_;
    // True for TIniFile (write-through), false for TMemIniFile (flush on
    // UpdateFile only).  Set by the ctors.
    bool writeThrough_;

    // Internal flush of the whole store to FileName.  Used by write-through
    // mutations (TIniFile) and by UpdateFile() (TMemIniFile).
    void flush();

private:
    // Tag ctor used by TMemIniFile to opt out of write-through and load eagerly.
    enum MemTag { kMem };
    TIniFile(const AnsiString& fileName, MemTag);
    friend class TMemIniFile;
};

// ===========================================================================
//  TMemIniFile  -- loads the ENTIRE file into memory at construction; reads /
//                  writes hit memory only; UpdateFile() is the ONLY disk flush
//                  (also flushed by the dtor as a safety net).
//                  common.cpp:353 (ctor), 362 (UpdateFile before delete).
// ===========================================================================
class TMemIniFile : public TIniFile {
public:
    explicit TMemIniFile(const AnsiString& fileName);
    virtual ~TMemIniFile();
    // UpdateFile() is inherited; for the Mem variant flush() actually writes the
    // in-memory image (writeThrough_==false, so mutations did NOT touch disk).
};

} // namespace vclcompat

#endif // VCLCOMPAT_INIFILES_H

TIniFile::TIniFile(const AnsiString& fileName, MemTag)
    : FileName(fileName), writeThrough_(false) {
    store_.LoadFromFile(fileName);
}

TIniFile::~TIniFile() {
    // Base TIniFile is write-through; nothing buffered to flush here. (The Mem
    // subclass overrides destruction order via its own dtor -> UpdateFile.)
}

void TIniFile::flush() {
    store_.SaveToFile(FileName, !writeThrough_);   // AI(W906-T4-INIFMT) 20260924: Mem variant = BCB6 TMemIniFile layout, so a golden-written file round-trips byte-identical; write-through TIniFile unchanged
}

AnsiString W906_DiskIniReadRaw(const AnsiString& file, const AnsiString& section, const AnsiString& ident, bool& found)
{
    return AnsiString(W906RdGetString(W906RdSlurp(file), section.c_str(), ident.c_str(), std::string(),
                                      kW906BcbReadStringBuf, &found));
}

AnsiString W906_Win32ProfileDefault(const AnsiString& def)
{
    return AnsiString(W906RdGetString(std::string(), std::string(), std::string(), def.c_str(), kW906BcbReadStringBuf, 0));
}

void W906_Win32WriteProfileString(const AnsiString& file, const AnsiString& section, const AnsiString& ident,
                                  const AnsiString& value)
{
    std::string buf; const int probe = W906_IniProbe(file); bool had = false;   //AI(W906-BOOTSPEED-2) 20260929: 0 = open as before, 1 = the file is not there, 2 = its directory is not there (see EOF)
    if (std::FILE* fp = (probe == 0 ? std::fopen(file.c_str(), "rb") : 0)) { had = true;   //AI(W906-BOOTSPEED-2) 20260929: a file the OS reports missing is not opened -- that open fails the same way (was: fopen on a missing path)
        char tmp[65536];
        size_t n;
        while ((n = std::fread(tmp, 1, sizeof tmp, fp)) > 0) buf.append(tmp, n);
        std::fclose(fp);
    }
    const std::string out = W906_IniApplyFast(buf, section.c_str(), ident.c_str(), value.c_str());   if (had && out == buf && W906_IniTouchSame(file)) return;   //AI(W906-BOOTSPEED-2) 20260929: bytes on disk already == the result -> stamp LastWriteTime (what kernel32 does, measured) instead of truncate + rewrite; W906_IniApplyFast = W906IniApply's bytes in one pass (both at EOF)
    if (std::FILE* fp = (probe == 2 ? 0 : std::fopen(file.c_str(), "wb"))) {   //AI(W906-BOOTSPEED-2) 20260929: no directory -> "wb" cannot create the file either (was: fopen on a missing directory)
        std::fwrite(out.data(), 1, out.size(), fp);
        std::fclose(fp);
    }
}

std::string W906RdSlurp(const AnsiString& file)
{
    std::string buf; if (W906_IniProbe(file) != 0) return buf;   //AI(W906-BOOTSPEED-2) 20260929: the OS reports the file (or its directory) missing -> the open below would fail the same way; skip its ~100-170 us under the on-access scanner (see EOF)
#ifdef _WIN32
    HANDLE h = ::CreateFileA(file.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, NULL,
                             OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return buf;
    LARGE_INTEGER sz;
    DWORD got = 0;
    if (::GetFileSizeEx(h, &sz) && sz.QuadPart > 0 && sz.QuadPart < 0x40000000) {   // one sized read (the common case)
        buf.resize((size_t)sz.QuadPart);
        if (!::ReadFile(h, &buf[0], (DWORD)buf.size(), &got, NULL)) got = 0;
        buf.resize(got);
    }
    char tmp[4096];                                    // whatever else is there (file grew / size unknown)
    while (::ReadFile(h, tmp, (DWORD)sizeof tmp, &got, NULL) && got > 0) buf.append(tmp, got);
    ::CloseHandle(h);
#else
    if (std::FILE* fp = std::fopen(file.c_str(), "rb")) {
        char tmp[65536];
        size_t n;
        while ((n = std::fread(tmp, 1, sizeof tmp, fp)) > 0) buf.append(tmp, n);
        std::fclose(fp);
    }
#endif
    return buf;
}

std::string W906RdGetString(const std::string& buf, const std::string& sec, const std::string& key,
                            const std::string& def, size_t size, bool* found)
{
    std::string v;
    const bool f = W906RdLookup(buf, sec, key, &v);
    if (!f) {
        v = def;
        while (!v.empty() && v[v.size() - 1] == ' ') v.erase(v.size() - 1);
    }
    if (size == 0) v.clear();
    else if (v.size() > size - 1) v.resize(size - 1);
    if (found) *found = f;
    return v;
}

bool W906RdLookup(const std::string& buf, const std::string& sec, const std::string& key, std::string* value)
{
    size_t pos = W906RdFindSection(buf, sec);
    if (pos == std::string::npos) return false;
    const W906RdSpan want = W906RdTrim(key.data(), key.size());
    W906RdSpan line, name, k, v;
    while (W906RdNextLine(buf, &pos, &line)) {
        if (W906RdHeader(line, &name)) break;
        if (W906RdKeyLine(line, &k, &v) && W906RdSame(k, want)) {
            if (v.n >= 2 && v.p[0] == v.p[v.n - 1] && (v.p[0] == '"' || v.p[0] == '\'')) { ++v.p; v.n -= 2; }
            value->assign(v.p, v.n);
            return true;
        }
    }
    return false;
}

bool W906RdNextLine(const std::string& buf, size_t* pos, W906RdSpan* line)
{
    const char* const b = buf.data();
    const char* const e = b + buf.size();
    const char* p = b + *pos;
    if (p >= e) return false;
    line->p = p;
    while (p < e && *p != '\r' && *p != '\n') ++p;
    line->n = (size_t)(p - line->p);
    if (p < e && *p == '\r' && p + 1 < e && p[1] == '\n') p += 2;
    else if (p < e) p += 1;
    *pos = (size_t)(p - b);
    return true;
}

bool W906RdHeader(const W906RdSpan& line, W906RdSpan* name)
{
    const W906RdSpan t = W906RdTrim(line.p, line.n);
    if (t.n == 0 || t.p[0] != '[') return false;
    const char* body = t.p + 1;
    size_t bn = t.n - 1;
    if (const void* close = std::memchr(body, ']', bn)) bn = (size_t)((const char*)close - body);
    *name = W906RdTrim(body, bn);
    return true;
}

bool W906RdKeyLine(const W906RdSpan& line, W906RdSpan* key, W906RdSpan* val)
{
    const W906RdSpan t = W906RdTrim(line.p, line.n);
    if (t.n == 0 || t.p[0] == ';') return false;
    const char* eq = (const char*)std::memchr(t.p, '=', t.n);
    if (!eq) return false;
    *key = W906RdTrim(t.p, (size_t)(eq - t.p));
    *val = W906RdTrim(eq + 1, (size_t)(t.p + t.n - eq - 1));
    return true;
}

bool W906RdSame(const W906RdSpan& a, const W906RdSpan& b)
{
    if (a.n != b.n) return false;
    for (size_t i = 0; i < a.n; ++i) {
        unsigned char x = (unsigned char)a.p[i], y = (unsigned char)b.p[i];
        if (x >= 'A' && x <= 'Z') x = (unsigned char)(x + 32);
        if (y >= 'A' && y <= 'Z') y = (unsigned char)(y + 32);
        if (x != y) return false;
    }
    return true;
}

int W906_IniProbe(const AnsiString& file)
{
#ifdef _WIN32
    if (::GetFileAttributesA(file.c_str()) != INVALID_FILE_ATTRIBUTES) return 0;
    const DWORD e = ::GetLastError();
    if (e == ERROR_FILE_NOT_FOUND) return 1;
    if (e == ERROR_PATH_NOT_FOUND) return 2;
#else
    (void)file;
#endif
    return 0;
}

W906RdSpan W906RdTrim(const char* p, size_t n)
{
    const char* e = p + n;
    while (p < e && (unsigned char)(*p - 1) < 0x20u) ++p;              // 0x01..0x20
    while (e > p && (unsigned char)(e[-1] - 1) < 0x20u) --e;
    W906RdSpan s = {p, (size_t)(e - p)};
    return s;
}

size_t W906RdFindSection(const std::string& buf, const std::string& sec)
{
    const W906RdSpan want = W906RdTrim(sec.data(), sec.size());
    size_t pos = 0;
    W906RdSpan line, name;
    while (W906RdNextLine(buf, &pos, &line))
        if (W906RdHeader(line, &name) && W906RdSame(name, want)) return pos;
    return std::string::npos;
}
